@using sv_28f3bc7d492c46aaa94510435d10e246.Services
@inject ISettingsService SettingsService

<div class="section-panel">
    <h4 class="mb-4">Appearance</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading appearance settings…</p>
    }
    else
    {
        @if (!string.IsNullOrEmpty(_successMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_successMessage
                <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
            </div>
        }

        <div class="row g-4">
            <!-- Theme -->
            <div class="col-md-6">
                <h6 class="fw-semibold mb-3">Theme</h6>
                @foreach (var theme in _themes)
                {
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <!-- Font Size -->
            <div class="col-md-6">
                <h6 class="fw-semibold mb-3">Font Size</h6>
                @foreach (var size in _fontSizes)
                {
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <!-- Language -->
            <div class="col-md-6">
                <h6 class="fw-semibold mb-3">Language</h6>
                <select class="form-select" @bind="_language" style="max-width:250px;">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="col-md-6">
                <h6 class="fw-semibold mb-3">Compact Mode</h6>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">
                        @(_compactMode ? "On" : "Off")
                    </label>
                </div>
            </div>

            <!-- Live Preview -->
            <div class="col-12">
                <h6 class="fw-semibold mb-3">Preview</h6>
                <div class="border rounded p-3"
                     style="@PreviewStyle()">
                    <h6 style="margin-bottom:0.5em;">Sample Heading</h6>
                    <p style="margin-bottom:0.5em;">
                        This is a preview of how your content will look with the selected settings.
                    </p>
                    <button class="btn btn-sm @PreviewButtonClass()">Sample Button</button>
                </div>
            </div>

            <!-- Save -->
            <div class="col-12">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>
            </div>
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _successMessage = "Appearance settings saved!";
        }
        finally
        {
            _saving = false;
        }
    }

    private string PreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background:#1e1e2e; color:#cdd6f4;",
            "System" => "background:#f0f0f0; color:#333;",
            _ => "background:#ffffff; color:#212529;"
        };

        var fs = _fontSize switch
        {
            "Small" => "font-size:0.85rem;",
            "Large" => "font-size:1.15rem;",
            _ => "font-size:1rem;"
        };

        var padding = _compactMode ? "padding:0.5rem;" : "padding:1rem;";

        return $"{bg} {fs} {padding} transition: all 0.2s ease;";
    }

    private string PreviewButtonClass() => _theme == "Dark" ? "btn-light" : "btn-primary";
}

