@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection"
                     OnSectionChanged="@(section => _activeSection = section)" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-dashboard {
    display: flex;
    gap: 2rem;
    min-height: 70vh;
}

.settings-sidebar {
    min-width: 200px;
    max-width: 220px;
    padding: 1rem 0;
    border-right: 1px solid var(--bs-border-color);
    flex-shrink: 0;
}

.settings-sidebar .nav-link {
    border-radius: 0.375rem;
    color: var(--bs-body-color);
    padding: 0.6rem 1rem;
    font-size: 0.95rem;
}

.settings-sidebar .nav-link:hover:not(.active) {
    background-color: var(--bs-tertiary-bg);
}

.settings-sidebar .nav-link.active {
    background-color: var(--bs-primary);
    color: #fff;
}

.settings-content {
    flex: 1;
    min-width: 0;
    padding: 1rem 0;
}

.section-panel {
    max-width: 800px;
}

::deep .sidebar-title {
    font-size: 1.1rem;
}

